// Variables used by Scriptable.
// YOS_SCRIPT_NAME: YOS Remote Web
// Existing Notion/GitHub remote code + saved YOS_Remote_Web.html design.
// Self-contained Scriptable WebView bridge; never exposes Keychain credentials to HTML.
// Does not modify existing remotes, installers, shortcuts or saved settings.
// Browser WebView + Keychain + LAN must run on user's iPhone. No hosted URL is created.
const tapo=(()=>{
  const module={exports:{}};
  // Variables used by Scriptable.
  // YOS_SCRIPT_NAME: YOS Tapo H110 Core
  // Shared Tapo H110 KLAP v2 core for Scriptable.
  // Credentials and remote map are stored only in Scriptable Keychain.
  
  const K = Object.freeze({
    host: 'yos.tapo.h110.host',
    user: 'yos.tapo.h110.user',
    pass: 'yos.tapo.h110.pass',
    map: 'yos.tapo.h110.remote-map'
  });
  
  function kc(key) { return Keychain.contains(key) ? Keychain.get(key) : ''; }
  function concat(...parts) { return parts.flatMap(x => Array.from(x || [])); }
  function utf8(s) { return Data.fromString(String(s)).getBytes(); }
  function b64(bytes) { return Data.fromBytes(Array.from(bytes)).toBase64String(); }
  function fromB64(s) { const d = Data.fromBase64String(s); return d ? d.getBytes() : []; }
  function eq(a,b){ if(!a||!b||a.length!==b.length)return false; let x=0; for(let i=0;i<a.length;i++)x|=a[i]^b[i]; return x===0; }
  function int32be(n){n|=0;return[(n>>>24)&255,(n>>>16)&255,(n>>>8)&255,n&255];}
  function readInt32be(bytes,off=0){return((bytes[off]<<24)|(bytes[off+1]<<16)|(bytes[off+2]<<8)|bytes[off+3])|0;}
  
  class WebCryptoBox {
    constructor(){ this.web = new WebView(); }
    async init(){
      await this.web.loadURL('https://example.com/');
      const injected = await this.web.evaluateJavaScript(`(() => {
        window.b2u=function(s){const x=atob(s),a=new Uint8Array(x.length);for(let i=0;i<x.length;i++)a[i]=x.charCodeAt(i);return a};
        window.u2b=function(a){let s='';const u=new Uint8Array(a);for(let i=0;i<u.length;i++)s+=String.fromCharCode(u[i]);return btoa(s)};
        window.dg=async function(alg,s){return u2b(await crypto.subtle.digest(alg,b2u(s)))};
        window.ae=async function(k,iv,d){const key=await crypto.subtle.importKey('raw',b2u(k),'AES-CBC',false,['encrypt']);return u2b(await crypto.subtle.encrypt({name:'AES-CBC',iv:b2u(iv)},key,b2u(d)))};
        window.ad=async function(k,iv,d){const key=await crypto.subtle.importKey('raw',b2u(k),'AES-CBC',false,['decrypt']);return u2b(await crypto.subtle.decrypt({name:'AES-CBC',iv:b2u(iv)},key,b2u(d)))};
        window.rnd=function(n){const a=new Uint8Array(n);crypto.getRandomValues(a);return u2b(a)};
        return String(!!(window.crypto&&crypto.subtle));
      })()`, false);
      if(String(injected)!=='true') throw new Error('暗号処理を初期化できませんでした。');
    }
    async call(expr){
      const js=`(() => {(async()=>{try{const value=await (${expr});completion(JSON.stringify({ok:1,v:value}));}catch(e){completion(JSON.stringify({ok:0,e:String(e)}));}})();return 'pending';})()`;
      const raw=await this.web.evaluateJavaScript(js,true);
      const out=JSON.parse(String(raw));
      if(!out.ok) throw new Error('暗号処理エラー: '+out.e);
      return out.v;
    }
    async digest(alg,bytes){return fromB64(await this.call(`dg(${JSON.stringify(alg)},${JSON.stringify(b64(bytes))})`));}
    async sha1(bytes){return this.digest('SHA-1',bytes);}
    async sha256(bytes){return this.digest('SHA-256',bytes);}
    async random(n){return fromB64(await this.call(`rnd(${Number(n)})`));}
    async aesEncrypt(key,iv,bytes){return fromB64(await this.call(`ae(${JSON.stringify(b64(key))},${JSON.stringify(b64(iv))},${JSON.stringify(b64(bytes))})`));}
    async aesDecrypt(key,iv,bytes){return fromB64(await this.call(`ad(${JSON.stringify(b64(key))},${JSON.stringify(b64(iv))},${JSON.stringify(b64(bytes))})`));}
  }
  
  class KlapV2 {
    constructor(host,username,password,crypto){this.host=host;this.username=username;this.password=password;this.crypto=crypto;this.cookie='';this.key=null;this.ivPrefix=null;this.sig=null;this.seq=0;}
    async post(path,bytes,cookie='',query=''){
      const r=new Request(`http://${this.host}/app/${path}${query}`);r.method='POST';r.timeoutInterval=8;r.headers={'Content-Type':'application/octet-stream'};if(cookie)r.headers.Cookie=cookie;r.body=Data.fromBytes(bytes);
      const data=await r.load();const status=r.response?r.response.statusCode:0;if(status<200||status>=300){const e=new Error(`H110通信エラー HTTP ${status}`);e.status=status;throw e;}return{bytes:data?data.getBytes():[],response:r.response||{}};
    }
    async authHash(){const u=await this.crypto.sha1(utf8(this.username));const p=await this.crypto.sha1(utf8(this.password));return this.crypto.sha256(concat(u,p));}
    async handshake(){
      const auth=await this.authHash();const local=await this.crypto.random(16);const h1=await this.post('handshake1',local);if(h1.bytes.length<48)throw new Error('H110のKLAP応答が不完全です。');
      const remote=h1.bytes.slice(0,16),serverHash=h1.bytes.slice(16,48),expected=await this.crypto.sha256(concat(local,remote,auth));if(!eq(expected,serverHash))throw new Error('Tapoアカウント認証に失敗しました。');
      const cookies=(h1.response&&h1.response.cookies)||[];const session=cookies.find(c=>c&&c.name==='TP_SESSIONID');if(!session)throw new Error('H110からセッションCookieを取得できませんでした。');this.cookie=`TP_SESSIONID=${session.value}`;
      await this.post('handshake2',await this.crypto.sha256(concat(remote,local,auth)),this.cookie);
      const keyHash=await this.crypto.sha256(concat(utf8('lsk'),local,remote,auth));const ivHash=await this.crypto.sha256(concat(utf8('iv'),local,remote,auth));const sigHash=await this.crypto.sha256(concat(utf8('ldk'),local,remote,auth));
      this.key=keyHash.slice(0,16);this.ivPrefix=ivHash.slice(0,12);this.seq=readInt32be(ivHash,28);this.sig=sigHash.slice(0,28);
    }
    async query(payload,retry=true){
      if(!this.key)await this.handshake();this.seq=(this.seq+1)|0;const seqBytes=int32be(this.seq),iv=concat(this.ivPrefix,seqBytes),clear=utf8(JSON.stringify(payload)),cipher=await this.crypto.aesEncrypt(this.key,iv,clear),signature=await this.crypto.sha256(concat(this.sig,seqBytes,cipher));
      try{const resp=await this.post('request',concat(signature,cipher),this.cookie,`?seq=${this.seq}`);if(resp.bytes.length<33)throw new Error('H110の暗号化応答が不完全です。');const plain=await this.crypto.aesDecrypt(this.key,iv,resp.bytes.slice(32)),text=Data.fromBytes(plain).toRawString();if(!text)throw new Error('H110応答を復号できませんでした。');const obj=JSON.parse(text);if(obj&&obj.error_code&&obj.error_code!==0)throw new Error(`Tapo error_code ${obj.error_code}`);return obj;}catch(e){if(retry&&(e.status===403||/session|security|403/i.test(String(e.message)))){this.key=null;this.cookie='';await this.handshake();return this.query(payload,false);}throw e;}
    }
    fire(deviceId,keyName){return this.fireBurst(deviceId,keyName,1);}
    fireBurst(deviceId,keyName,count=1){
      const n=Math.max(1,Math.min(6,Number(count)||1));
      const requests=Array.from({length:n},()=>({method:'sendIrCmdById',params:{name:keyName}}));
      return this.query({method:'control_child',params:{device_id:deviceId,requestData:{method:'multipleRequest',params:{requests}}}});
    }
    controlAc(deviceId,state){return this.query({method:'control_child',params:{device_id:deviceId,requestData:{method:'multipleRequest',params:{requests:[{method:'sendIrCmdByStatus',params:state}]}}}});}
  }
  
  function getCredentials(){
    const host=kc(K.host),user=kc(K.user),pass=kc(K.pass);if(!host||!user||!pass)throw new Error('先に YOS Tapo H110 Setup を実行してください。');return{host,user,pass};
  }
  function getMap(){try{return JSON.parse(kc(K.map)||'[]');}catch(_){return[];}}
  function findRemote(predicate){const map=getMap();return map.find(predicate)||null;}
  function findKey(remote,candidates){
    if(!remote||!Array.isArray(remote.keys))return null;
    const norm=s=>String(s||'').trim().toLowerCase();
    for(const c of candidates){const n=norm(c);const k=remote.keys.find(x=>norm(x.name)===n||norm(x.label)===n);if(k)return k;}
    return null;
  }
  async function client(){const c=getCredentials();const crypto=new WebCryptoBox();await crypto.init();return new KlapV2(c.host,c.user,c.pass,crypto);}
  // Optional device-specific local connection. Keep the existing H110 client unchanged.
  async function clientForHost(host){
    const name=String(host||'').trim();
    if(!/^(?:\d{1,3}\.){3}\d{1,3}$/.test(name)||name.split('.').some(x=>Number(x)>255))throw Error('IPアドレス不正');
    const c=getCredentials();
    const crypto=new WebCryptoBox();
    await crypto.init();
    return new KlapV2(name,c.user,c.pass,crypto);
  }
  
  async function fireFriendly(remotePredicate,keyCandidates){
    const remote=findRemote(remotePredicate);if(!remote)throw new Error('対象リモコンが見つかりません。Setupを再実行してください。');const key=findKey(remote,keyCandidates);if(!key)throw new Error('対象ボタンが見つかりません。');const c=await client();await c.fire(remote.device_id,key.name);return{remote,key};
  }
  
  module.exports={K,getCredentials,getMap,findRemote,findKey,client,clientForHost,fireFriendly};
  
  return module.exports;
})();

const STORAGE=Object.freeze({
  host:"yos.bravia.scriptable.host",
  psk:"yos.bravia.scriptable.psk"
});

const ALIASES=Object.freeze({
 power:["poweroff","power"], input:["input"],home:["home"],back:["return","back"],
 up:["up"],down:["down"],left:["left"],right:["right"],confirm:["confirm","enter"],
 volumeDown:["volumedown"],mute:["mute"],volumeUp:["volumeup"]
});
const ACTIONS=Object.freeze(Object.fromEntries(Object.keys(ALIASES).map(key=>[key,{label:key}])));
function secure(key){return Keychain.contains(key)?Keychain.get(key):""}
function normalizeHost(value){
  const host=String(value||"").trim().replace(/^https?:\/\//i,"").replace(/:\d+$/,"");
  if(!host||/[\s/?#]/.test(host))throw new Error("テレビのIPアドレスまたはホスト名を確認してください。");
  return host;
}
function xmlEscape(v){
  return String(v).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&apos;");
}

async function discover(host,psk){
  const r=new Request("http://"+host+"/sony/system");
  r.method="POST";
  r.headers={"Content-Type":"application/json","X-Auth-PSK":psk};
  r.body=JSON.stringify({method:"getRemoteControllerInfo",params:[],id:1,version:"1.0"});
  const data=JSON.parse(await r.loadString());
  const commands=data&&data.result&&data.result[1];
  if(!Array.isArray(commands))throw new Error("BRAVIAコマンド取得失敗");
  const index=new Map();
  commands.forEach(item=>{
    if(item&&item.name&&item.value)index.set(String(item.name).toLowerCase(),String(item.value));
  });
  return index;
}

async function runAction(action){
  if(!ACTIONS[action])throw new Error("不明なBRAVIA操作です。");
  const host=normalizeHost(secure(STORAGE.host));
  const psk=secure(STORAGE.psk);
  if(!psk)throw new Error("BRAVIA PSK設定なし");
  const index=await discover(host,psk);
  let code=null;
  for(const alias of ALIASES[action]||[]){
    if(index.has(alias.toLowerCase())){code=index.get(alias.toLowerCase());break;}
  }
  if(!code)throw new Error("このテレビでは未対応です："+action);
  const r=new Request("http://"+host+"/sony/ircc");
  r.method="POST";
  r.headers={
    "Content-Type":"text/xml; charset=UTF-8",
    "X-Auth-PSK":psk,
    SOAPACTION:'"urn:schemas-sony-com:service:IRCC:1#X_SendIRCC"'
  };
  r.body='<?xml version="1.0"?><s:Envelope xmlns:s="http://schemas.xmlsoap.org/soap/envelope/"><s:Body><u:X_SendIRCC xmlns:u="urn:schemas-sony-com:service:IRCC:1"><IRCCCode>'+xmlEscape(code)+'</IRCCCode></u:X_SendIRCC></s:Body></s:Envelope>';
  await r.loadString();
}


async function tvOff(){
  const host=String(Keychain.get(KEYS.tvHost)).replace(/^https?:\/\//,"").replace(/\/$/,"");
  async function rpc(method,params){
    const req=new Request("http://"+host+"/sony/system");
    req.method="POST";req.timeoutInterval=8;
    req.headers={"Content-Type":"application/json","X-Auth-PSK":Keychain.get(KEYS.tvPsk)};
    req.body=JSON.stringify({method,params,id:1,version:"1.0"});
    const json=JSON.parse(await req.loadString());
    if(json.error)throw Error("BRAVIA応答エラー");
    return json.result;
  }
  const state=(await rpc("getPowerStatus",[]))?.[0]?.status;
  if(!["active","standby"].includes(state))throw Error("BRAVIA電源状態が不明のため中止");
  if(state==="active")await rpc("setPowerStatus",[{status:false}]);
  return state==="active"?"OFF指令送信":"既に待機中";
}

function acRemote(){
  const r=tapo.findRemote(x=>String(x.model||'').toUpperCase()==='AC'||/エアコン|air.?con/i.test(String(x.nickname||'')));
  if(!r)throw Error('SHARPエアコンの既存H110リモコン設定が見つかりません');
  return r;
}
const FAN_STEPS=Object.freeze([0,1,3]);
const FAN_LABELS=Object.freeze({0:'自動',1:'弱',3:'強'});
function fanName(s){const n=Number(s&&s.S);return Object.prototype.hasOwnProperty.call(FAN_LABELS,n)?FAN_LABELS[n]:(Number.isFinite(n)?String(n):'自動');}
function nextFanValue(value){const n=Number(value),i=FAN_STEPS.indexOf(n);return FAN_STEPS[i>=0?(i+1)%FAN_STEPS.length:0];}
function walk(value,out=[]){if(Array.isArray(value))for(const v of value)walk(v,out);else if(value&&typeof value==='object'){out.push(value);for(const v of Object.values(value))walk(v,out);}return out;}
async function getClientAndState(){
  const client=await tapo.client();
  const raw=await client.query({method:'control_child',params:{device_id:acRemote().device_id,requestData:{method:'get_device_info',params:null}}});
  const info=walk(raw,[]).find(x=>typeof x.ac_status==='string')||{};
  const s={};
  if(typeof info.ac_status==='string')for(const part of info.ac_status.split('_')){const m=String(part).match(/^([PMTSD])(-?\d+)$/);if(m)s[m[1]]=Number(m[2]);}
  if(s.P==null&&info.on!=null)s.P=Number(info.on);
  if(s.M==null&&info.ac_mode!=null)s.M=Number(info.ac_mode);
  if(s.T==null&&info.current_temp!=null)s.T=Number(info.current_temp);
  if(s.S==null&&info.wind_speed!=null)s.S=Number(info.wind_speed);
  if(s.D==null&&info.wind_direct!=null)s.D=Number(info.wind_direct);
  if(!Number.isFinite(s.P))s.P=0;
  if(!Number.isFinite(s.M))s.M=0;
  if(!Number.isFinite(s.T))s.T=26;
  if(!Number.isFinite(s.S))s.S=0;
  if(!Number.isFinite(s.D))s.D=6;
  return {client,state:s};
}
function payload(s){return{power:!!s.P,on:!!s.P,mode:Number(s.M),temp:Math.max(18,Math.min(30,Number(s.T)||26)),wind_speed:Math.max(0,Math.min(4,Number(s.S)||0)),wind_direct:Math.max(0,Math.min(6,Number(s.D)||0))};}
async function acRunAction(action){
  const {client,state:s}=await getClientAndState();
  if(action==='cool'){s.P=1;s.M=0;s.T=Math.max(18,Math.min(30,s.T||26));}
  else if(action==='dry'){s.P=1;s.M=4;s.S=0;}
  else if(action==='heat'){s.P=1;s.M=1;s.T=Math.max(18,Math.min(30,s.T||26));}
  else if(action==='stop'){s.P=0;}
  else if(action==='tempUp'){if(s.M===4)return;s.P=1;s.T=Math.min(30,(s.T||26)+1);}
  else if(action==='tempDown'){if(s.M===4)return;s.P=1;s.T=Math.max(18,(s.T||26)-1);}
  else if(action==='fan'){if(s.M===4)return;s.P=1;s.S=nextFanValue(s.S);}
  else if(action==='wind'){s.P=1;s.D=(s.D+1)%7;}
  else throw new Error('不明なエアコン操作です。');
  await client.controlAc(acRemote().device_id,payload(s));
}

const LIGHT_KEYS=Object.freeze({
 on:['POWER ON','点灯'],off:['POWER OFF','消灯'],
 bright:['BRIGHTNESS+','明るくする','明るい'],dark:['BRIGHTNESS-','暗くする','暗い'],
 night:['常夜灯','Night Light']
});
function lightRemote(){return tapo.findRemote(r=>/ライト|light/i.test(String(r.nickname||''))||String(r.model||'').toLowerCase()==='light');}
async function ceiling(action){
  const keys=LIGHT_KEYS[action];if(!keys)throw Error('未対応の照明操作');
  const remote=lightRemote();if(!remote)throw Error('天井照明の登録がありません');
  const key=tapo.findKey(remote,keys);if(!key)throw Error('照明の該当ボタンが登録されていません');
  const client=await tapo.client();
  // A triple brightness step replaces 3 separate screen taps; other keys are single sends.
  await client.fireBurst(remote.device_id,key.name,(action==='bright'||action==='dark')?3:1);
  return '天井照明へ命令を送信しました（赤外線のため状態未取得）';
}
function floorInfo(raw){
  if(!raw||typeof raw!=='object')return null;
  if(typeof raw.device_on==='boolean')return raw;
  for(const x of Object.values(raw)){const info=floorInfo(x);if(info)return info;}
  return null;
}
function rgbToHsv(hex){
  const rgb=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255);
  const max=Math.max(...rgb),min=Math.min(...rgb),delta=max-min;
  let hue=0; if(delta){if(max===rgb[0])hue=((rgb[1]-rgb[2])/delta)%6;else if(max===rgb[1])hue=(rgb[2]-rgb[0])/delta+2;else hue=(rgb[0]-rgb[1])/delta+4;}
  hue=Math.round((hue*60+360)%360);
  return{hue,saturation:Math.round(max===0?0:delta/max*100)};
}
async function floor(action,value){
  const key='yos.tapo.floor.local-host';
  if(!Keychain.contains(key)||!String(Keychain.get(key)||'').trim())throw Error('ランプのIP設定がありません');
  const client=await tapo.clientForHost(String(Keychain.get(key)).trim());
  const before=floorInfo(await client.query({method:'get_device_info',params:null}));
  if(!before)throw Error('ランプの現在状態を読めないため操作を中止');
  let params;
  if(action==='on'||action==='off'){
    const want=action==='on';if(before.device_on===want)return want?'ランプは既に点灯しています':'ランプは既に消灯しています';
    params={device_on:want};
  }else if(action==='brightness'){
    if(!Number.isInteger(value)||value<1||value>100)throw Error('明るさが範囲外');
    if(typeof before.brightness!=='number')throw Error('このランプの明るさ設定は未確認');
    params={device_on:true,brightness:value};
  }else if(action==='color'){
    if(typeof value!=='string'||!/^#[0-9a-f]{6}$/i.test(value))throw Error('色の指定が不正');
    if(typeof before.hue!=='number'||typeof before.saturation!=='number')throw Error('このランプの色操作は未確認');
    params={device_on:true,color_temp:0,...rgbToHsv(value)};
  }else if(['warm','natural','daywhite','daylight'].includes(action)){
    if(typeof before.color_temp!=='number')throw Error('このランプの白色切替は未確認');
    const kelvin={warm:2700,natural:3500,daywhite:4000,daylight:5000}[action];
    let range=before.color_temp_range;
    if(Array.isArray(range)&&range.length===2&&(kelvin<range[0]||kelvin>range[1]))throw Error('このランプの対応色温度範囲外');
    params={device_on:true,color_temp:kelvin};
  }else throw Error('未対応のランプ操作');
  await client.query({method:'set_device_info',params});
  return 'ランプに命令を送信しました（実機への反映は別途確認）';
}
async function scene(action){
  if(action==='sleep'){const a=await floor('on');const b=await tvOff();const c=await ceiling('off');return '就寝モード：'+[a,b,c].join(' / ');}
  if(action==='movie'){const a=await floor('on');const b=await ceiling('off');return 'シアターモード：'+a+' / '+b+'（TV電源はそのまま）';}
  if(action==='morning'){const a=await ceiling('on');const b=await floor('off');return '起床モード：'+a+' / '+b+'（TVとエアコンは変更しません）';}
  if(action==='allOff'){const result=[];result.push(await floor('off'));result.push(await ceiling('off'));await tvOff();result.push('テレビ OFF');await runActionAC('stop');result.push('エアコン停止指令');return '一括OFF：'+result.join(' / ');}
  throw Error('未対応のシーン');
}
// Rename source-derived actions to avoid accidental BRAVIA/AC function collision.
async function runActionTV(action){return await runAction(action);}
async function runActionAC(action){return await acRunAction(action);}
function checkCommand(task){
  if(!task||typeof task!=='object')throw Error('操作データが不正');
  const groups={tv:['power','input','home','back','up','down','left','right','confirm','volumeDown','mute','volumeUp'],
    light:['on','off','bright','dark','night'],
    ac:['cool','dry','heat','stop','tempDown','tempUp'],
    floor:['on','off','color','brightness','warm','natural','daywhite','daylight'],
    scene:['movie','sleep','morning','allOff']};
  if(!Object.prototype.hasOwnProperty.call(groups,task.device)||!groups[task.device].includes(task.action))throw Error('未対応の操作');
  if(task.action==='color'&&!(typeof task.value==='string'&&/^#[0-9a-f]{6}$/i.test(task.value)))throw Error('色の指定が不正');
  if(task.action==='brightness'&&!(Number.isInteger(task.value)&&task.value>=1&&task.value<=100))throw Error('明るさが範囲外');
  if(!['color','brightness'].includes(task.action)&&task.value!==undefined)throw Error('不要な値を受信');
  return {device:task.device,action:task.action,value:task.value};
}
async function dispatch(task){
  const command=checkCommand(task);
  if(command.device==='tv'){await runActionTV(command.action);return 'テレビへ命令を送信しました';}
  if(command.device==='light')return await ceiling(command.action);
  if(command.device==='ac'){await runActionAC(command.action);return 'エアコンへ命令を送信しました';}
  if(command.device==='floor')return await floor(command.action,command.value);
  if(command.device==='scene')return await scene(command.action);
  throw Error('操作できません');
}
